const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Arrachart, Madagascar coordinates (approximately -19.43, 45.29)
  const arrachart = ee.Geometry.Point([45.29, -19.43]);
  const buffer = arrachart.buffer(5000); // 5km buffer for analysis

  // 2. Define January 2020
  const startDate = '2020-01-01';
  const endDate = '2020-01-31';

  // 3. Load CHIRPS rainfall data
  let col = ee.ImageCollection('UCSB-CHG/CHIRPS/PENTAD')
    .filterDate(startDate, endDate)
    .filterBounds(buffer);

  const colSize = col.size().getInfo();
  console.log(`CHIRPS PENTAD images found: ${colSize}`);

  if (colSize === 0) {
    // Try daily CHIRPS as fallback
    col = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
      .filterDate(startDate, endDate)
      .filterBounds(buffer);
    const colSizeDaily = col.size().getInfo();
    console.log(`CHIRPS DAILY images found: ${colSizeDaily}`);

    if (colSizeDaily === 0) {
      console.log('No rainfall data available for January 2020 at Arrachart.');
      console.log('C1');
      return;
    }
  }

  // 4. Sum all precipitation for January 2020
  const totalPrecip = col.sum();

  // 5. Calculate mean precipitation over the region
  const precipStats = totalPrecip.reduceRegion(
    {
      reducer: ee.Reducer.mean(),
      geometry: buffer,
      scale: 5000,
      maxPixels: 1e9
    }
  );

  const precipMM = precipStats.get('precipitation').getInfo();
  console.log(`Total precipitation (mm): ${precipMM}`);

  // Check for valid pixels
  const pixelCount = totalPrecip.reduceRegion(
    {
      reducer: ee.Reducer.count(),
      geometry: buffer,
      scale: 5000,
      maxPixels: 1e9
    }
  ).get('precipitation').getInfo();

  console.log(`Valid pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log('No valid pixels after processing.');
    console.log('C2');
    return;
  }

  if (precipMM === null || isNaN(precipMM)) {
    console.log('Calculation resulted in null or NaN.');
    console.log('C3');
    return;
  }

  // 6. Convert mm to inches (1 inch = 25.4 mm)
  const precipInches = precipMM / 25.4;
  console.log(`Total precipitation (inches): ${precipInches.toFixed(2)}`);

  // 7. Compare to 22 inches threshold
  const threshold = 22;
  if (precipInches > threshold) {
    console.log(`${precipInches.toFixed(2)} inches > ${threshold} inches`);
    console.log('A');
  } else {
    console.log(`${precipInches.toFixed(2)} inches <= ${threshold} inches`);
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
